from journal.engine.nudge import Nudge
from journal.engine.nudge_kind import NudgeKind
from journal.support.timeout import Timeout


class WorkersNudges:
    EDIT_LOCK = Nudge("workers", "worktree_being_rebased", "the journal is rebasing your worktree; writes wait until it is done", "wait a moment, then write again", repeat=Timeout.seconds(0))
    TEST_QUEUE = Nudge("workers", "queue_the_tests", "do not run {{command|cap=24}}; queue the tests", "`journal tests turn <test>`, single tests", repeat=Timeout.seconds(0))
    BUILD_QUEUE = Nudge("workers", "queue_the_build", "do not run {{command|cap=24}}; queue the build", "`journal build`", repeat=Timeout.seconds(0))
    COMMAND_KIND_REFUSAL = Nudge("workers", "workers_only_edit", "a worker only reads, searches and edits, not {{command|cap=24}}", "queue tests and builds with the journal", repeat=Timeout.seconds(0))
    SUBAGENT_COMMAND_REFUSAL = Nudge("workers", "subagents_only_read", "a subagent only reads and searches, not {{command|cap=24}}", "", repeat=Timeout.seconds(0))
    WORKER_GIT_REFUSAL = Nudge("workers", "worker_runs_no_git", "never run git; the journal commits at clock-out", "on a clash, fix the files, then `journal clock-out \"<report>\"`", repeat=Timeout.seconds(0))
    OUTPUT_UNFINISHED = Nudge("workers", "own_output_running", "output {{n}} still runs and ends when you stop", "wait for it, then stop", repeat=Timeout.seconds(0))
    OUTPUT_END = Nudge("workers", "own_output_ended", "output {{n}} ended with code {{status}}", "read it with `journal output read {{n}} --summary`", repeat=Timeout.seconds(0))
    USER_CLOSURE = Nudge("workers", "task_closed_by_user", "the user closed your task {{task}}", "stop now", repeat=Timeout.seconds(0))
    OPEN_TODOS = Nudge("workers", "open_todos", "{{count}} to-dos open: {{items|cap=34}}", "finish them, or say why in `journal clock-out \"<report>\"`", repeat=Timeout.seconds(0))
    WORK_READY = Nudge("workers", "work_ready", "worker {{n}} ready: task {{task}}", repeat=Timeout.seconds(0))
    BRANCH_KEEPS_CLASHING = Nudge("workers", "branch_keeps_clashing", "worker {{n}}'s branch rebased {{clashes}} times in a row, clashing in {{clashing|cap=25}}", "let it merge before the others", repeat=Timeout.seconds(0))
    RUN_UNFINISHED = Nudge("workers", "run_unfinished", "worker {{n}} ended without clocking out{{cause|cap=82}}", repeat=Timeout.seconds(0))
    WORKER_REPORTED = Nudge("workers", "worker_reported", "worker {{n}} reported", repeat=Timeout.seconds(0))
    STARTED_PLANS = Nudge("workers", "started_plans", "started plans: {{plans|cap=400}}", repeat=Timeout.minutes(10), blocks_regardless=True, longest_characters=425, longest_reason="it lists every started plan with its counts", kind=NudgeKind.REMARK)
    DELIVERED_WAITING = Nudge("workers", "clocked_out_work_waits", "{{workers|cap=16}} clocked out", "check each point with `journal worker check <n> <point>`, then `journal worker merge <n>`", repeat=Timeout.seconds(0))
    ACTIVE_WORKERS = Nudge("workers", "wait_for_running_workers", "{{workers|cap=19}} are still out and nothing waits to be checked", "wait with `journal worker wait {{numbers|cap=19}}`", repeat=Timeout.seconds(0), kind=NudgeKind.REMARK)
    MEMORY_WARNING = Nudge("workers", "worker_uses_much_memory", "worker {{n}} uses {{megabytes}} MB, over the {{budget}} MB warning", "check what it runs; it stops at the memory limit", repeat=Timeout.seconds(0))
    WORKER_LIMITED = Nudge("workers", "worker_waits_for_the_usage_limit", "worker {{n}} stopped at the usage limit; it resumes by itself at {{at}}", repeat=Timeout.seconds(0))
    IDLE_WORKER = Nudge("workers", "worker_has_no_work_left", "worker {{n}} idle: queue it tasks or `journal worker complete {{n}} --why \"<why>\"`", "", repeat=Timeout.seconds(0))
    QUEUE_RELATED = Nudge("workers", "queue_the_related_tasks", "queue tasks {{listed|cap=16}} of task {{task}}'s plan on {{worker}}: `journal worker queue {{n}} {{tasks|cap=16}}`", "", repeat=Timeout.minutes(60))
    PLACE_OPENED = Nudge("workers", "place_opened", "your load stayed at {{rho}} for {{minutes}} minutes: one place more, {{places|cap=29}} workers out at once", repeat=Timeout.seconds(0))
    PLACE_CLOSED = Nudge("workers", "place_closed", "your load stayed at {{rho}} for {{minutes}} minutes: one place fewer, {{places|cap=28}} workers out at once", repeat=Timeout.seconds(0))
    WAIT_TEXT = Nudge("workers", "make_the_wait_a_block", "block instead of waiting: `journal task block <n> --on task:<m>` or `journal task block <n> --until '<command>'`", "", repeat=Timeout.minutes(30))
    TEST_RUN_FAILED = Nudge("workers", "worker_test_run_failed", "worker {{n}}: {{failed}} failed in its test run", repeat=Timeout.seconds(0))
    WORKER_KEEPS_FAILING = Nudge("workers", "worker_keeps_failing", "worker {{n}} failed {{runs}} test runs in a row", repeat=Timeout.seconds(0))
    WORKER_STOPPED_UNREPORTED = Nudge("workers", "worker_stopped_unreported", "worker {{n}} stopped before it reported{{cause|cap=82}}", repeat=Timeout.seconds(0))
    SUBAGENT_OVERFLOW = Nudge("workers", "too_many_subagents", "{{running}} subagents are running, the most allowed", "wait for one, or do it yourself", repeat=Timeout.seconds(0))
    PLACES_FULL = Nudge("workers", "places_full_check_work", "all places full", "check worker {{n}} first to free one", repeat=Timeout.tool_uses(30))
    PLACES_FULL_OWNER = Nudge("workers", "places_full_ask_plan_seat", "all places full", "{{owner}} must free a place", repeat=Timeout.tool_uses(30))
    WORKER_OVERFLOW = Nudge("workers", "too_many_workers", "{{out}} workers are out, the most allowed", "run `journal worker wait <n>`, or send the job to one that reported", repeat=Timeout.seconds(0))
    WORKER_FILE = Nudge("workers", "file_is_the_workers", "that file is in worker {{n}}'s worktree", "`journal worker send {{n}} \"<job>\"`, or wait for its report and merge", repeat=Timeout.seconds(0))
    UNREAD_WORKER_REPORTS = Nudge("workers", "act_on_the_reports", "{{reports_waiting}} reported", "give it its next job with `journal worker send <n> \"<job>\"`, stop it, or mark it done", repeat=Timeout.seconds(180), blocks_regardless=True)
    WORKER_KNOWS_FILES = Nudge("workers", "send_it_to_the_worker_that_knows", "{{count}} idle workers worked on this job's files: {{workers|cap=400}}", "send the job to one, or add `--fresh` to the dispatch", repeat=Timeout.seconds(0), longest_characters=511, longest_reason="it lists each idle worker with the command that sends it the job")
    IDLE_CAP = Nudge("workers", "send_it_to_an_idle_worker", "{{count}} of {{total}} {{profile}} workers are idle: {{workers|cap=400}}", "send the job to one", repeat=Timeout.seconds(0), longest_characters=480, longest_reason="it lists each idle worker with the command that sends it the job")
    REUSE_QUESTION = Nudge("workers", "could_it_be_reused", "if worker {{n}} can do this, run `journal worker send {{n}} \"<job>\"`; if not, repeat the command with `--why \"<why>\"`", "", repeat=Timeout.seconds(0))
    SILENT_WORKER = Nudge("workers", "worker_quiet", "worker {{n}} silent {{minutes}} min; last: {{last|cap=20}}", "notify it or stop it", repeat=Timeout.seconds(0))
    WORKER_LOG_DUE = Nudge("workers", "worker_log_due", "you logged nothing for {{minutes}} min", "log where you stand: `journal todo add \"<step>\"` or `journal proof <point> \"<proof>\"`", repeat=Timeout.seconds(0))
    PROOF_REJECTED = Nudge("workers", "worker_sent_back", "worker {{n}} back on point {{point}}", repeat=Timeout.seconds(0))
    PROOF_REJECTED_REPEAT = Nudge("workers", "worker_sent_back_again", "worker {{n}} back on point {{point}} again; earlier: {{earlier|cap=73}}", repeat=Timeout.seconds(0))
    PROOF_REJECTED_OFTEN = Nudge("workers", "worker_sent_back_repeatedly", "point {{point}} failed {{times}} times on {{model}} ({{earlier|cap=16}})", "`journal worker send {{n}} --model <model> \"<job>\"`", repeat=Timeout.seconds(0))
    SUBAGENT_REUSE = Nudge("workers", "send_the_job_to_the_subagent", "{{count}} idle subagents already worked on this job's files: {{subagents|cap=400}}", "send the job to one with SendMessage", repeat=Timeout.seconds(0), longest_characters=504, longest_reason="it lists each idle subagent with the line that sends it the job")
